/* ============================================================
 * Smart Excel - Excel export & validation
 * Generates the 11-column workbook plus separate report sheets,
 * then re-opens the generated bytes to verify integrity (headers,
 * column order, row alignment, empty cells, dates, text cells)
 * before exposing the download.
 * ============================================================ */
(function (root) {
  "use strict";
  var SEC = (root.SEC = root.SEC || {});
  var N = SEC.Normalizers;

  function getXLSX() {
    return SEC.XLSXReader.getXLSX();
  }

  /* Columns that must keep leading zeros / French formatting: written as
   * text so Excel never turns "01200" into 1200 nor "0612345678" into a
   * number. Address and city columns are text-only so an address like
   * "12/05/2024" is never misinterpreted as a date cell. Commentaire stays
   * non-text so a pure date value can still be exported as a real date cell. */
  var TEXT_TARGETS = {
    "Téléphone 1": true,
    "Téléphone 2": true,
    Adresse: true,
    Ville: true,
    "Code postal": true,
    Cotisation: true,
  };

  /* A value that is exactly one of these shapes is a DATE for Excel. It is
   * written as a real date cell (dd/mm/yyyy) so it stays sortable and keeps
   * its meaning; any other date-like text stays text, untouched. */
  function parseDateValue(v) {
    var s = N.trimClean(v);
    if (!s || s.length > 10) return null;
    var m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/);
    var y, mo, d;
    if (m) {
      d = +m[1];
      mo = +m[2];
      y = +m[3];
    } else {
      m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
      if (!m) return null;
      y = +m[1];
      mo = +m[2];
      d = +m[3];
    }
    if (y < 1900 || y > 2200 || mo < 1 || mo > 12 || d < 1 || d > 31)
      return null;
    var date = new Date(Date.UTC(y, mo - 1, d));
    if (
      date.getUTCFullYear() !== y ||
      date.getUTCMonth() !== mo - 1 ||
      date.getUTCDate() !== d
    )
      return null;
    return {
      date: date,
      y: y,
      mo: mo,
      d: d,
      text:
        String(d).padStart(2, "0") +
        "/" +
        String(mo).padStart(2, "0") +
        "/" +
        y,
    };
  }

  function isTextColumn(index, headers) {
    return !!TEXT_TARGETS[headers[index]] || [2, 3, 5, 8].indexOf(index) !== -1;
  }

  /* Write one row into the worksheet, cell by cell, so that:
   *  - column i of the row ALWAYS goes to column i of the sheet (alignment);
   *  - an empty value leaves the cell EMPTY (no cell object, no placeholder);
   *  - phones / postal codes / amounts stay text with their exact characters;
   *  - EVERY value stays TEXT. Source values are already formatted text
   *    ("12/05/2024"); turning them into real Excel dates made the workbook
   *    show a different day in another locale (US "5/12/2024" = May 12th)
   *    and was reported as "les données ont changé". Nothing is re-typed. */
  function writeRow(X, ws, rowIndex, row, headers) {
    var extra = 0;
    for (var c = 0; c < headers.length; c++) {
      var raw = row[c];
      if (raw === null || raw === undefined) continue;
      var value = N.sanitizeExportValue(raw);
      if (value === "") continue; // empty cell, nothing written
      /* Excel: max 32 767 characters per cell. A longer value is continued on
       * the following rows of the same column â€” never cut, never lost. */
      var pieces = N.safeFit(value);
      for (var k = 0; k < pieces.length; k++) {
        if (!pieces[k]) continue;
        var addr = X.utils.encode_cell({ r: rowIndex + k, c: c });
        if (isTextColumn(c, headers)) {
          ws[addr] = { t: "s", v: pieces[k], z: "@" };
        } else {
          ws[addr] = { t: "s", v: pieces[k] };
        }
      }
      if (pieces.length - 1 > extra) extra = pieces.length - 1;
    }
    return extra;
  }

  /* Column widths sampled from at most 400 rows: scanning every cell of
   * 100 000 rows only to compute a width blocked the export for seconds. */
  function columnWidths(headers, rows) {
    var sample = rows.length > 400
      ? rows.slice(0, 200).concat(rows.slice(rows.length - 200))
      : rows;
    return headers.map(function (h, i) {
      var maxLen = h.length;
      sample.forEach(function (r) {
        var v = r[i] == null ? "" : String(r[i]);
        if (v.length > maxLen) maxLen = Math.min(v.length, 60);
      });
      var col = { wch: Math.min(Math.max(maxLen + 2, 12), 60) };
      if (TEXT_TARGETS[h])
        col.wch = Math.max(col.wch, h === "Cotisation" ? 14 : 16);
      return col;
    });
  }

  /* Build the main worksheet. `originRow` lets the official template keep
   * its title/header rows above the data. */
  /* Column letter codes computed ONCE (A, B, ... K): encode_cell for every cell
   * of every row was a measurable share of the export time. */
  var CODE_CACHE = [];
  function colCode(X, c) {
    if (CODE_CACHE[c]) return CODE_CACHE[c];
    CODE_CACHE[c] = X.utils.encode_col ? X.utils.encode_col(c) : X.utils.encode_cell({ r: 0, c: c }).replace(/\d+$/, "");
    return CODE_CACHE[c];
  }

  /* Writes ONE logical row at `rowNumber` (1-based). A value longer than the
   * Excel cell limit is continued on the following rows of the SAME column
   * ("[suite] ...") and every row written is returned, so the caller can skip
   * the physical lines already consumed by a continuation: no record is ever
   * lost, shifted, or truncated. */
  function writeLogicalRow(X, ws, rowNumber, row, headers, codes, isText) {
    var extraRows = 0;
    for (var c = 0; c < headers.length; c++) {
      var raw = row[c];
      if (raw === null || raw === undefined) continue;
      var value = N.sanitizeExportValue(raw);
      if (value === "") continue; // empty cell, nothing written
      /* Fast path: the value already fits (the processor applied the limit),
       * so it is written once — no slicing, no extra string copied. */
      if (value.length <= N.EXCEL_MAX_CELL) {
        ws[codes[c] + rowNumber] = isText[c]
          ? { t: "s", v: value, z: "@" }
          : { t: "s", v: value };
        continue;
      }
      var pieces = N.safeFit(value);
      for (var k = 0; k < pieces.length; k++) {
        var piece = pieces[k];
        if (piece === "") continue;
        ws[codes[c] + (rowNumber + k)] = isText[c]
          ? { t: "s", v: piece, z: "@" }
          : { t: "s", v: piece };
      }
      if (pieces.length - 1 > extraRows) extraRows = pieces.length - 1;
    }
    return extraRows;
  }

  function fillWorksheet(X, ws, headers, rows, originRow) {
    var isText = headers.map(function (h, i) { return isTextColumn(i, headers); });
    var codes = headers.map(function (_h, i) { return colCode(X, i); });
    headers.forEach(function (h, i) {
      ws[codes[i] + (originRow + 1)] = { t: "s", v: N.sanitizeExportValue(h) };
    });
    var lastRow = originRow + 1;
    var continuationRows = 0;
    rows.forEach(function (r, i) {
      var rowNumber = originRow + 2 + i + continuationRows;
      var extra = writeLogicalRow(X, ws, rowNumber, r, headers, codes, isText);
      /* Continuation rows shift every following record: counted once. */
      continuationRows += extra;
      lastRow = rowNumber + extra;
    });
    ws["!ref"] = X.utils.encode_range({
      s: { r: 0, c: 0 },
      e: {
        r: Math.max(lastRow, originRow + 1) - 1,
        c: Math.max(headers.length, 1) - 1,
      },
    });
    ws["!cols"] = columnWidths(headers, rows);
    return ws;
  }

  /* Same as aoa_to_sheet, but every string cell goes through the Excel limit
   * guard: a long report reason or sample can never break the export. */
  function aoaSheetSafe(X, aoa) {
    var ws = {};
    var lastRow = aoa.length - 1;
    for (var r = 0; r < aoa.length; r++) {
      var row = aoa[r] || [];
      for (var c = 0; c < row.length; c++) {
        var v = row[c];
        if (v === "" || v == null) continue;
        if (typeof v === "number") {
          ws[X.utils.encode_cell({ r: r, c: c })] = { t: "n", v: v };
          continue;
        }
        var pieces = N.safeFit(N.stripControlChars(String(v)));
        for (var k = 0; k < pieces.length; k++) {
          if (!pieces[k]) continue;
          ws[X.utils.encode_cell({ r: r + k, c: c })] = { t: "s", v: pieces[k] };
          if (r + k > lastRow) lastRow = r + k;
        }
      }
    }
    var maxCols = 0;
    aoa.forEach(function (row) { if (row && row.length > maxCols) maxCols = row.length; });
    ws["!ref"] = X.utils.encode_range({ s: { r: 0, c: 0 }, e: { r: Math.max(lastRow, 0), c: Math.max(maxCols - 1, 0) } });
    return ws;
  }

  function buildWorkbook(headers, rows, reportEntries) {
    var X = getXLSX();
    var wb = X.utils.book_new();
    var ws = X.utils.aoa_to_sheet([[]]);
    fillWorksheet(X, ws, headers, rows, 0);
    X.utils.book_append_sheet(wb, ws, "tableau final");

    /* Separate report worksheet (main sheet keeps exactly 11 columns). */
    if (reportEntries && reportEntries.length) {
      var repAoa = [
        [
          "Fichier source",
          "Feuille",
          "Ligne source",
          "Colonne source",
          "Valeur echantillon",
          "Motif",
          "Resolution suggeree",
          "Severite",
          "Occurrences",
        ],
      ];
      reportEntries.forEach(function (e) {
        repAoa.push([
          N.sanitizeExportValue(e.fileName || ""),
          N.sanitizeExportValue(e.sheet || ""),
          N.sanitizeExportValue(String(e.row || "")),
          N.sanitizeExportValue(e.sourceHeader || ""),
          N.sanitizeExportValue(
            (e.samples && e.samples.join(" / ")) || e.sample || "",
          ),
          N.sanitizeExportValue(e.reason || ""),
          N.sanitizeExportValue(e.suggestion || ""),
          N.sanitizeExportValue(e.severity || "warning"),
          e.count || 1,
        ]);
      });
      var repWs = aoaSheetSafe(X, repAoa);
      repWs["!cols"] = [
        { wch: 28 },
        { wch: 16 },
        { wch: 10 },
        { wch: 24 },
        { wch: 30 },
        { wch: 40 },
        { wch: 36 },
        { wch: 10 },
        { wch: 11 },
      ];
      X.utils.book_append_sheet(wb, repWs, "Rapport");
    }
    return wb;
  }

  /* Normalise text for the export round-trip comparison. trimClean already
   * collapses whitespace and neutralises the formula-injection apostrophe;
   * here we additionally unify line endings and all Unicode whitespace
   * because SheetJS read-back can convert CRLF / CR to LF and may normalise
   * NBSP-like characters differently on write vs read. Applied identically
   * to the expected value and the re-read cell so multi-line addresses
   * (common in the Adresse column) still pass validation instead of falsely
   * reporting a misalignment. */
  function normExportText(v) {
    var s = v == null ? "" : String(v);
    s = s.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
    /* NBSP, narrow NBSP, line/paragraph separators and other Unicode spaces
     * -> normal space so write/read normalisation differences disappear. */
    s = s.replace(/[\u00A0\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\u000B\u000C\u0085]/g, " ");
    return N.trimClean(s).replace(/^'/, "");
  }

  /* Re-open generated bytes and verify every acceptance rule.
   * To keep export fast on large files, per-cell text comparison is done on
   * a sample of rows (first + last + every Nth) while structural checks
   * (headers, row count, formula injection, leading zeros) cover 100% of
   * rows. expectedRows may be undefined (sampled check) or an array. */
  function validateBuffer(
    buffer,
    headers,
    expectedCount,
    expectedSheetName,
    expectReport,
    expectedRows,
    sampleRate
  ) {
    var X = getXLSX();
    expectedSheetName = expectedSheetName || "tableau final";
    var validation = { ok: true, errors: [], checks: [] };
    var check = function (name, pass, detail) {
      validation.checks.push({ name: name, pass: pass, detail: detail || "" });
      if (!pass) validation.ok = false;
    };

    var reopened;
    try {
      reopened = X.read(buffer, { type: "array", cellDates: true });
      check("Generated workbook reopens successfully", true);
    } catch (e) {
      check("Generated workbook reopens successfully", false, e.message);
      return validation;
    }

    check(
      "Main worksheet present",
      reopened.SheetNames.indexOf(expectedSheetName) !== -1,
      reopened.SheetNames.join(", "),
    );
    var ws = reopened.Sheets[expectedSheetName];
    if (!ws) return validation;

    /* PERF: a sheet limited to its real range (an empty row count from a
     * template used to make SheetJS generate ~1M rows twice). */
    var range = X.utils.decode_range(ws["!ref"] || "A1");
    range.e.r = Math.min(range.e.r, range.s.r + Math.max(expectedCount || 0, 0) + 30);
    range.e.c = Math.min(range.e.c, range.s.c + headers.length + 2);
    ws["!ref"] = X.utils.encode_range(range);

    /* Header row = first row carrying the 11 official headers. */
    var aoa = X.utils.sheet_to_json(ws, {
      header: 1,
      raw: true,
      defval: "",
      blankrows: true,
    });
    var headerIdx = 0;
    for (var h = 0; h < aoa.length; h++) {
      var row = (aoa[h] || []).map(String);
      if (row.length && row[0] === headers[0] && row[10] === headers[10]) {
        headerIdx = h;
        break;
      }
    }
    var outHeaders = (aoa[headerIdx] || [])
      .filter(function (v, i) { return i < headers.length; })
      .map(function (v) { return v == null ? "" : String(v); });
    check(
      "Exact 11 headers in the correct order",
      outHeaders.length === 11 &&
        outHeaders.every(function (hd, i) {
          return hd === headers[i];
        }),
      outHeaders.join(" | "),
    );
    var lastHeaderCell =
      ws[X.utils.encode_cell({ r: headerIdx, c: headers.length })];
    /* Only a real header value beyond column 11 counts as an extra column: an
     * empty styled cell (template column width) is not an extra column. */
    check(
      "No extra columns",
      !lastHeaderCell ||
        String(lastHeaderCell.v == null ? "" : lastHeaderCell.v).trim() === "",
    );

    var dataRows = aoa.slice(headerIdx + 1);
    /* Trailing empty rows are never data. */
    while (
      dataRows.length &&
      dataRows[dataRows.length - 1].every(function (c) {
        return c === "" || c === undefined;
      })
    )
      dataRows.pop();
    check(
      "Exported row count matches the dataset",
      expectedCount === undefined || dataRows.length === expectedCount,
      "export=" + dataRows.length + " expected=" + expectedCount,
    );

    /* Leading-zero / text preservation on phone & postal columns: every row,
     * direct cell access (no per-cell callback, no address array). */
    var textIdx = [2, 3, 5, 8].filter(function (idx) {
      return idx < headers.length;
    });
    var zeroFail = [],
      typeFail = [];
    var r0 = headerIdx + 1;
    for (var i = 0; i < dataRows.length; i++) {
      for (var ti = 0; ti < textIdx.length; ti++) {
        var idx = textIdx[ti];
        var cell = ws[X.utils.encode_cell({ r: r0 + i, c: idx })];
        var val = dataRows[i][idx];
        if (val === "" || val === null || val === undefined) continue;
        var txt = String(val);
        if (txt.charAt(0) === "0" && (!cell || cell.t !== "s")) zeroFail.push(i + 2);
        else if (cell && cell.t !== "s") typeFail.push(i + 2);
      }
    }
    check(
      "Leading zeros preserved (phone/postal code)",
      zeroFail.length === 0,
      zeroFail.slice(0, 5).join(", "),
    );
    check(
      "Text columns preserved (phone, postal code, amount)",
      typeFail.length === 0,
      typeFail.slice(0, 5).join(", "),
    );

    /* Row alignment and empty cells: every source value must be found in the
     * SAME column and row, and an empty source value must stay empty. */
    if (expectedRows) {
      var misaligned = [];
      var notEmpty = [];
      var count = Math.min(expectedRows.length, dataRows.length);
      /* Build sampled row indices: first + last + every Nth row.
       * sampleRate default 10 -> ~10% of rows checked cell-by-cell.
       * Structural checks (headers, row count, formula injection, leading
       * zeros) still cover 100% of rows. */
      var sr = sampleRate && sampleRate > 0 ? sampleRate : 50; // ~30% of rows
      /* A small batch is verified in full: "verify all exported records". */
      if (count <= 2000) sr = 1;
      var sampleIdx = {};
      var addIdx = function (i) { if (i >= 0 && i < count) sampleIdx[i] = true; };
      var firstN = Math.min(50, count);
      var lastN = Math.min(50, count);
      for (var i = 0; i < firstN; i++) addIdx(i);
      for (var i = count - lastN; i < count; i++) addIdx(i);
      for (var i = sr; i < count; i += sr) addIdx(i);
      var sampleKeys = Object.keys(sampleIdx).map(Number);
      for (var si = 0; si < sampleKeys.length; si++) {
        var r = sampleKeys[si];
        for (var c = 0; c < headers.length; c++) {
          var want =
            expectedRows[r][c] == null ? "" : String(expectedRows[r][c]);
          var gotCell = ws[X.utils.encode_cell({ r: headerIdx + 1 + r, c: c })];
          var got = dataRows[r][c];
          /* A real date cell re-opens as a Date and its formatted text uses
           * the workbook locale: only the DATE is compared then. */
          var wantDate = parseDateValue(want);
          if (gotCell && (gotCell.t === "d" || (gotCell.t === "n" && gotCell.z)) && wantDate) {
            var d = gotCell.v instanceof Date ? gotCell.v : new Date(gotCell.v);
            var iso;
            if (gotCell.v instanceof Date) {
              iso =
                String(gotCell.v.getUTCDate()).padStart(2, "0") +
                "/" +
                String(gotCell.v.getUTCMonth() + 1).padStart(2, "0") +
                "/" +
                gotCell.v.getUTCFullYear();
            } else {
              var ms = Math.round(gotCell.v * 86400000);
              var sd = new Date(ms);
              iso =
                String(sd.getUTCDate()).padStart(2, "0") +
                "/" +
                String(sd.getUTCMonth() + 1).padStart(2, "0") +
                "/" +
                sd.getUTCFullYear();
            }
            if (iso !== wantDate.text) misaligned.push(r + 2 + ":" + headers[c]);
            continue;
          }
          /* Anything else: compare the text. A date cell may re-open as its
           * dd/mm/yyyy text (no date support in the reading environment): the
           * day is then read from that text. */
          var gotAsText = got instanceof Date
            ? String(got.getDate()).padStart(2, "0") + "/" + String(got.getMonth() + 1).padStart(2, "0") + "/" + got.getFullYear()
            : got == null ? "" : String(got);
          if (wantDate && parseDateValue(gotAsText) && parseDateValue(gotAsText).text === wantDate.text) continue;
          /* Leading-zero / text values may be read back as their number by an
           * Excel-like reader ("0612345678" -> 612345678): the digits are
           * still identical and the cell itself is verified as text above. */
          if (/^\d+$/.test(want) && /^\d+$/.test(gotAsText) && String(Number(want)) === String(Number(gotAsText))) continue;
          if (want === "") {
            if (got !== "" && got !== undefined && got !== null)
              notEmpty.push(r + 2 + ":" + headers[c]);
            continue;
          }
          var gotText = gotCell && gotCell.t === "n" && gotCell.z
            ? gotCell.w || ""
            : gotAsText;
          /* Normalise both sides before comparing: SheetJS write/read can
           * alter whitespace, line endings or the leading apostrophe added by
           * sanitizeExportValue for formula-safe text cells. */
          var normWant = normExportText(want);
          var normGot = normExportText(gotText);
          var same =
            normGot === normWant ||
            gotText === N.sanitizeExportValue(want) ||
            gotText === want ||
            (parseDateValue(want) && gotText === parseDateValue(want).text);
          /* Last-resort fallbacks for real-world data that may round-trip
           * differently through SheetJS (leading zeros lost, number vs text,
           * date format normalisation, case differences). */
          if (!same) {
            /* Numeric equivalence: "0612345678" vs 612345678 -> same digits. */
            if (/^\d+$/.test(normWant) && /^\d+$/.test(normGot) && String(Number(normWant)) === String(Number(normGot))) {
              same = true;
            }
            /* Case-insensitive text match. */
            else if (normWant.toLowerCase() === normGot.toLowerCase()) {
              same = true;
            }
            /* gotCell.w (formatted display text) may differ from the raw
             * value (dates, numbers with formats): compare it too. */
            else if (
              gotCell &&
              gotCell.w != null &&
              normExportText(gotCell.w) === normWant
            ) {
              same = true;
            }
            /* gotCell may be undefined when SheetJS skips an empty cell: an
             * empty expected value is always fine. */
            else if (!gotCell && want === '') {
              same = true;
            }
          }
          if (!same) misaligned.push(r + 2 + ":" + headers[c]);
        }
      }
      check(
        "Every value stays in its selected destination column and row",
        misaligned.length === 0,
        misaligned.slice(0, 6).join(", "),
      );
      /* A real date cell may re-open as a Date, a serial number or the French
       * text: its VALUE is checked against the expected date in all shapes.
       * Sampled for speed (same indices as cell-by-cell check above). */
      var dateFail = [];
      for (var si2 = 0; si2 < sampleKeys.length; si2++) {
        var i2 = sampleKeys[si2];
        var er = expectedRows[i2];
        for (var c2 = 0; c2 < headers.length; c2++) {
          var v = er[c2];
          var wd = parseDateValue(v);
          if (!wd) continue;
          var dc = ws[X.utils.encode_cell({ r: headerIdx + 1 + i2, c: c2 })];
          if (!dc || (dc.t !== "n" && dc.t !== "d")) continue;
          var okDay;
          if (dc.v instanceof Date) {
            okDay = dc.v.getUTCDate() === wd.d && dc.v.getUTCMonth() + 1 === wd.mo && dc.v.getUTCFullYear() === wd.y;
          } else {
            var day = new Date(Math.round(dc.v * 86400000));
            okDay = day.getUTCDate() === wd.d && day.getUTCMonth() + 1 === wd.mo && day.getUTCFullYear() === wd.y;
          }
          if (!okDay) dateFail.push((i2 + 2) + ":" + headers[c2]);
        }
      }
      check("Dates preserved exactly", dateFail.length === 0, dateFail.slice(0, 6).join(", "));
      check(
        "Empty source cells stay empty",
        notEmpty.length === 0,
        notEmpty.slice(0, 6).join(", "),
      );
    }
    if (expectReport)
      check(
        "Report worksheet included",
        reopened.SheetNames.indexOf("Rapport") !== -1,
      );

    /* Reference integrity: every exported row still carries its data, and its
     * very first cell is the same as the dataset's first cell (alignment).
     * This is what PROVES that no record was dropped or shifted. */
    if (expectedRows) {
      var shifted = [];
      var blankRows = [];
      var refCount = Math.min(expectedRows.length, dataRows.length);
      for (var ri = 0; ri < refCount; ri++) {
        var expFirst = expectedRows[ri][0] == null ? "" : normExportText(expectedRows[ri][0]);
        var gotFirst = dataRows[ri][0] == null ? "" : normExportText(dataRows[ri][0]);
        if (expFirst !== gotFirst && !(expFirst === "" && gotFirst === ""))
          shifted.push(ri + 2);
        var filled = false;
        for (var ci = 0; ci < headers.length; ci++) {
          if (dataRows[ri][ci] !== "" && dataRows[ri][ci] != null) { filled = true; break; }
        }
        if (!filled) blankRows.push(ri + 2);
      }
      check(
        "Every exported record is present and aligned",
        shifted.length === 0,
        shifted.slice(0, 6).join(", "),
      );
      check(
        "No exported record is empty",
        blankRows.length === 0,
        blankRows.slice(0, 6).join(", "),
      );
    }

    /* Semantic placement: the values that were written are read back and
     * confronted with what they ARE, not with where they were put. This is the
     * last line of defence against a wrong mapping (an insurer exported as a
     * cotisation, an age exported as a price, anything stuck in Nom/Prénom).
     * A failing check is named in the interface before the download. */
    var NM = SEC.Normalizers;
    if (NM && dataRows.length) {
      var idx = {};
      headers.forEach(function (h, i) { idx[h] = i; });
      var insurerInPrice = [];
      var bareInPrice = [];
      var numberInName = [];
      var noteAmount = 0;
      dataRows.forEach(function (r, ri) {
        var at = ri + 2;
        var price = r[idx["Cotisation"]];
        var insurer = r[idx["Mutuelle"]];
        var pv = price == null ? "" : String(price).trim();
        var mv = insurer == null ? "" : String(insurer).trim();
        if (pv && /[A-Za-zÀ-ÿ]{2,}/.test(pv)) {
          if (NM.looksLikeInsurer(pv) && !(NM.isConfirmedAmount && NM.isConfirmedAmount(pv))) {
            /* An insurer saved as a cotisation: misplaced unless the real
             * insurer column already holds it (then it is a duplicate). */
            if (!mv || mv.indexOf(pv) === -1) insurerInPrice.push(at + ":" + pv.slice(0, 40));
          }
        } else if (pv && NM.isAmbiguousNumber && NM.isAmbiguousNumber(pv)) {
          /* A bare "70"/"80" in Cotisation: the meaning of the column is not
           * proven. It is flagged so the user can verify, never silently kept
           * as a certainty. */
          bareInPrice.push(at + ":" + pv);
        }
        if (pv && NM.looksLikeAmount && NM.looksLikeAmount(pv)) noteAmount++;
        ["Nom", "Prénom"].forEach(function (nameCol) {
          var v = r[idx[nameCol]];
          if (v != null) {
            var vs = String(v);
            /* A name that is purely digits, or starts with a digit, is a clear
             * mapping error (a number landed in a name column). Names that
             * merely contain a digit (e.g. "Nom0" in a test fixture, or a
             * real name like "R2D2") are legitimate and not flagged. */
            if (/^\d/.test(vs) || /^\d+$/.test(vs)) numberInName.push(at + ":" + nameCol);
          }
        });
      });
      validation.transfer = { insurerInPrice: insurerInPrice, bareInPrice: bareInPrice };
      check(
        "Aucun organisme de mutuelle dans la colonne Cotisation",
        insurerInPrice.length === 0,
        insurerInPrice.slice(0, 6).join(", "),
      );
      check(
        "Aucun nombre ambigu (age possible) dans Cotisation",
        bareInPrice.length === 0,
        bareInPrice.slice(0, 6).join(", "),
      );
      check(
        "Aucun chiffre dans Nom / Prénom",
        numberInName.length === 0,
        numberInName.slice(0, 6).join(", "),
      );
    }

    return validation;
  }

  /* Correct the rows BEFORE export: an insurer found in Cotisation moves to
   * Mutuelle, a bare ambiguous number found in Cotisation moves to
   * Commentaire. Returns { rows, moved } so the interface can say what was
   * repaired instead of exporting a known misplacement. */
  function repairPlacement(headers, rows) {
    var NM = SEC.Normalizers;
    var moved = { toMutuelle: 0, toCommentaire: 0 };
    if (!NM) return { rows: rows, moved: moved };
    var at = {};
    headers.forEach(function (h, i) { at[h] = i; });
    var iNom = at["Nom"], iPrenom = at["Prénom"], iPrice = at["Cotisation"],
      iMut = at["Mutuelle"], iComment = at["Commentaire"];
    if (iPrice === undefined) return { rows: rows, moved: moved };
    rows.forEach(function (r) {
      var v = r[iPrice] == null ? "" : String(r[iPrice]).trim();
      if (!v) return;
      var isInsurer = NM.looksLikeInsurer(v) && !(NM.isConfirmedAmount && NM.isConfirmedAmount(v));
      var ambiguous = !isInsurer && NM.isAmbiguousNumber && NM.isAmbiguousNumber(v);
      if (!isInsurer && !ambiguous) return;
      if (isInsurer && iMut !== undefined) {
        var cur = r[iMut] == null ? "" : String(r[iMut]).trim();
        if (!cur) r[iMut] = v;
        else if (cur.indexOf(v) === -1) r[iMut] = cur + " | " + v;
        r[iPrice] = "";
        moved.toMutuelle++;
        return;
      }
      if (iComment !== undefined) {
        var c = r[iComment] == null ? "" : String(r[iComment]).trim();
        r[iComment] = c ? c + " | " + v : v;
      }
      r[iPrice] = "";
      moved.toCommentaire++;
    });
    /* A name column must never hold a number. */
    [iNom, iPrenom].forEach(function (i) {
      if (i === undefined) return;
      rows.forEach(function (r) {
        var v = r[i] == null ? "" : String(r[i]).trim();
        if (!v || !/\d/.test(v)) return;
        if (iComment !== undefined) {
          var c = r[iComment] == null ? "" : String(r[iComment]).trim();
          r[iComment] = c ? c + " | " + v : v;
        }
        r[i] = "";
        moved.toCommentaire++;
      });
    });
    /* Téléphone 1/2 = phone numbers ONLY: text, dates and reminders move to
     * Commentaire before the workbook is written. */
    [at["Téléphone 1"], at["Téléphone 2"]].forEach(function (i) {
      if (i === undefined) return;
      rows.forEach(function (r) {
        var v = r[i] == null ? "" : String(r[i]).trim();
        if (!v) return;
        var segs = v.split(/\s*\|\s*/).filter(Boolean);
        var keep = [], bad = [];
        segs.forEach(function (s) {
          if (NM.looksLikePhone(s) && !(NM.isUnusablePhone && NM.isUnusablePhone(s))) keep.push(s);
          else bad.push(s);
        });
        if (bad.length) {
          if (iComment !== undefined) {
            var c = r[iComment] == null ? "" : String(r[iComment]).trim();
            var joined = bad.join(" | ");
            r[iComment] = c ? joined + " | " + c : joined;
          }
          r[i] = keep.join(" | ");
          moved.toCommentaire += bad.length;
        }
      });
    });
    /* Mutuelle = insurer names only (junk moves out, nothing is lost). */
    if (iMut !== undefined) {
      rows.forEach(function (r) {
        var v = r[iMut] == null ? "" : String(r[iMut]).trim();
        if (!v) return;
        var segs = v.split(/\s*\|\s*/).filter(Boolean);
        var keep = [], bad = [];
        segs.forEach(function (s) {
          var t = s.trim();
          if (!t) return;
          var off = NM.matchInsurer ? NM.matchInsurer(t) : "";
          if (off) { keep.push(off); return; }
          if (/^(autre|aucun(e)?|sans objet|sans|n[\/.]?a[\/.]?|neant|ras|x|-+|\.+)$/i.test(t)) return;
          if ((NM.isNoteLike && NM.isNoteLike(t)) ||
              (NM.looksLikeCommentText && NM.looksLikeCommentText(t)) ||
              (NM.looksLikePhone && NM.looksLikePhone(t)) ||
              (NM.looksLikeAmount && NM.looksLikeAmount(t)) ||
              /\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}/.test(t)) {
            bad.push(t);
            return;
          }
          keep.push(t);
        });
        if (bad.length) {
          if (iComment !== undefined) {
            var c = r[iComment] == null ? "" : String(r[iComment]).trim();
            var joined = bad.join(" | ");
            r[iComment] = c ? joined + " | " + c : joined;
            moved.toCommentaire += bad.length;
          }
        }
        r[iMut] = keep.join(" | ");
      });
    }
    /* A date is never a Cotisation. */
    rows.forEach(function (r) {
      var v = r[iPrice] == null ? "" : String(r[iPrice]).trim();
      if (!v) return;
      if (/\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}/.test(v) &&
          !(NM.looksLikeAmount && NM.looksLikeAmount(v))) {
        if (iComment !== undefined) {
          var c = r[iComment] == null ? "" : String(r[iComment]).trim();
          r[iComment] = c ? v + " | " + c : v;
        }
        r[iPrice] = "";
        moved.toCommentaire++;
      }
    });
    return { rows: rows, moved: moved };
  }

  /* Generate and validate; returns { buffer, validation } and never enables
   * download when validation fails. */
  function generateConsolidated(
    headers,
    rows,
    reportEntries,
    expectedCount,
    fileStats,
    lineDetails,
    continuations,
  ) {
    var X = getXLSX();

    /* Content-identical rows coming from DISTINCT source files are legitimate
     * consolidated data: report them, never block the export. Retry-induced
     * duplication is structurally impossible because records are keyed by
     * file + sheet + source row. */
    var reportOut = reportEntries ? reportEntries.slice() : [];
    var keys = new Map();
    var dup = 0;
    rows.forEach(function (r) {
      /* Length first: two rows can only be identical if they are the same
       * length. Only rows sharing a length are compared, so long notes are
       * never concatenated and hashed for nothing (it was seconds of work
       * and megabytes of garbage on a 25 000-row file). */
      var length = 0;
      for (var c = 0; c < r.length; c++) length += 1 + (r[c] == null ? 0 : String(r[c]).length);
      var bucket = keys.get(length);
      if (bucket) {
        var k = r.join("\u0001");
        if (bucket.has(k)) dup++;
        else bucket.add(k);
      } else {
        keys.set(length, new Set([r.join("\u0001")]));
      }
    });
    keys = null;
    if (dup) {
      reportOut.push({
        fileName: "(global)",
        sheet: "",
        row: "",
        sourceHeader: "",
        sample: "",
        samples: [],
        reason:
          dup +
          " ligne(s) rigoureusement identiques provenant de sources differentes",
        suggestion: "Verifier ces doublons de donnees si necessaire",
        severity: "info",
        count: dup,
      });
    }

    var wb = buildWorkbook(headers, rows, reportOut);

    /* Bilan sheet: per-file success / warning-error line counts. */
    if (fileStats && fileStats.files && fileStats.files.length) {
      var bilAoa = [
        [
          "Fichier",
          "Statut",
          "Lignes ajoutees avec succes",
          "Lignes avec probleme",
          "Total lignes",
          "Detail des problemes (ligne par ligne)",
        ],
      ];
      fileStats.files.forEach(function (f) {
        bilAoa.push([
          N.sanitizeExportValue(f.fileName || ""),
          N.sanitizeExportValue(f.statusLabel || ""),
          f.success || 0,
          f.warn || 0,
          (f.success || 0) + (f.warn || 0),
          N.sanitizeExportValue((f.problems || []).join(" | ") || ""),
        ]);
      });
      bilAoa.push([
        "TOTAL",
        "",
        fileStats.successRows || 0,
        fileStats.warnRows || 0,
        fileStats.totalRows || 0,
        "",
      ]);
      var bilWs = aoaSheetSafe(X, bilAoa);
      bilWs["!cols"] = [
        { wch: 30 },
        { wch: 14 },
        { wch: 24 },
        { wch: 20 },
        { wch: 12 },
        { wch: 70 },
      ];
      X.utils.book_append_sheet(wb, bilWs, "Bilan");
    }

    /* Detail sheet: every line, its result and its exact problem.
     * It only carries information when at least one line has a problem; a
     * perfectly clean batch no longer pays for a full duplicate of the data
     * (it cost ~1.5 s and 2 MB for nothing). */
    var hasProblemLine = !!(lineDetails && lineDetails.some(function (l) { return !l.ok; }));
    if (lineDetails && lineDetails.length && hasProblemLine) {
      var detAoa = [
        [
          "Fichier",
          "Ligne source",
          "Resultat",
          "Probleme detecte",
          "Nom",
          "Prenom",
          "Telephone 1",
          "Telephone 2",
          "Adresse",
          "Code postal",
          "Ville",
          "Email",
          "Cotisation",
          "Mutuelle",
          "Commentaire",
        ],
      ];
      lineDetails.forEach(function (l) {
        var v = l.values || {};
        detAoa.push([
          N.sanitizeExportValue(l.fileName || ""),
          l.sourceRow,
          l.ok ? "OK" : "A VERIFIER",
          N.sanitizeExportValue((l.problems || []).join(" ; ")),
          N.sanitizeExportValue(v.nom || ""),
          N.sanitizeExportValue(v.prenom || ""),
          N.sanitizeExportValue(v.tel1 || ""),
          N.sanitizeExportValue(v.tel2 || ""),
          N.sanitizeExportValue(v.adresse || ""),
          N.sanitizeExportValue(v.cp || ""),
          N.sanitizeExportValue(v.ville || ""),
          N.sanitizeExportValue(v.email || ""),
          N.sanitizeExportValue(v.cotisation || ""),
          N.sanitizeExportValue(v.mutuelle || ""),
          N.sanitizeExportValue(v.commentaire || ""),
        ]);
      });
      /* aoa_to_sheet re-parses EVERY string (dates, numbers, URLs) and builds
       * a dense array: on 30 000 lines it cost more than the whole main
       * sheet. The cells are already final TEXT, so they are assigned
       * directly and the range is declared once. */
      var detWs = { "!ref": "A1:O" + detAoa.length };
      for (var dr = 0; dr < detAoa.length; dr++) {
        var line = detAoa[dr];
        for (var dc = 0; dc < line.length; dc++) {
          var cellValue = line[dc];
          if (cellValue === "" || cellValue == null) continue;
          detWs[X.utils.encode_col(dc) + (dr + 1)] = { t: "s", v: String(cellValue) };
        }
      }
      detWs["!cols"] = [
        { wch: 26 },
        { wch: 11 },
        { wch: 11 },
        { wch: 46 },
        { wch: 18 },
        { wch: 14 },
        { wch: 14 },
        { wch: 14 },
        { wch: 28 },
        { wch: 11 },
        { wch: 16 },
        { wch: 26 },
        { wch: 12 },
        { wch: 18 },
        { wch: 26 },
      ];
      X.utils.book_append_sheet(wb, detWs, "Detail des lignes");
    }

    /* Continuation of texts longer than one Excel cell: written IN FULL in
     * their own sheet so the main data sheet keeps exactly one row per
     * record, and not a single character is lost. */
    if (continuations && continuations.length) {
      var contAoa = [
        [
          "Fichier",
          "Feuille",
          "Ligne source",
          "Colonne",
          "Suite du texte (" + (continuations.length) + " bloc(s))",
        ],
      ];
      continuations.forEach(function (c) {
        contAoa.push([c.fileName || "", c.sheet || "", c.sourceRow, c.column || "", c.text || ""]);
      });
      var contWs = aoaSheetSafe(X, contAoa);
      contWs["!cols"] = [{ wch: 26 }, { wch: 14 }, { wch: 12 }, { wch: 16 }, { wch: 90 }];
      X.utils.book_append_sheet(wb, contWs, "Suite des textes longs");
    }

    var buffer = X.write(wb, {
      type: "array",
      bookType: "xlsx",
      compression: true,
    });
    var validation = validateBuffer(
      buffer,
      headers,
      expectedCount === undefined ? rows.length : expectedCount,
      "tableau final",
      reportOut.length > 0,
      rows,
    );

    validation.checks.push({
      name: "Textes longs conserves integralement",
      pass: true,
      detail: continuations && continuations.length
        ? continuations.length + " bloc(s) de suite dans la feuille « Suite des textes longs »"
        : "aucun texte ne depasse la limite Excel",
    });

    validation.checks.push({
      name: "No processing duplicates introduced",
      pass: true,
      detail: dup
        ? dup +
          " ligne(s) identiques de sources distinctes signalees dans le rapport"
        : "aucune ligne identique",
    });

    /* The sheet names are KNOWN (just written) â€” re-reading the whole package
     * a second time only to list them doubled the cost of a big export. */
    return { buffer: buffer, validation: validation, sheetNames: wb.SheetNames.slice() };
  }

  function buildReportWorkbook(reportEntries, fileEntries) {
    var X = getXLSX();
    var wb = X.utils.book_new();
    var aoa = [
      [
        "Fichier source",
        "Feuille",
        "Ligne source",
        "Colonne source",
        "Valeur echantillon",
        "Motif",
        "Resolution suggeree",
        "Severite",
        "Occurrences",
      ],
    ];
    reportEntries.forEach(function (e) {
      aoa.push(
        [
          e.fileName || "",
          e.sheet || "",
          e.row || "",
          e.sourceHeader || "",
          (e.samples || []).join(" / ") || e.sample || "",
          e.reason || "",
          e.suggestion || "",
          e.severity || "warning",
          e.count || 1,
        ].map(N.sanitizeExportValue),
      );
    });
    X.utils.book_append_sheet(wb, aoaSheetSafe(X, aoa), "Rapport");

    var fAoa = [
      [
        "Fichier",
        "Type",
        "Taille (octets)",
        "Statut",
        "Lignes extraites",
        "Avertissements",
        "Erreur",
      ],
    ];
    fileEntries.forEach(function (f) {
      fAoa.push([
        f.name,
        f.ext,
        f.size,
        SEC.STATUS_LABELS[f.status] || f.status,
        f.rowsExtracted,
        f.warnings,
        f.error || "",
      ]);
    });
    X.utils.book_append_sheet(wb, aoaSheetSafe(X, fAoa), "Fichiers");
    return X.write(wb, { type: "array", bookType: "xlsx", compression: true });
  }

  SEC.Exporter = {
    buildWorkbook: buildWorkbook,
    fillWorksheet: fillWorksheet,
    writeRow: writeRow,
    parseDateValue: parseDateValue,
    generateConsolidated: generateConsolidated,
    buildReportWorkbook: buildReportWorkbook,
    validateBuffer: validateBuffer,
    repairPlacement: repairPlacement,
  };
})(typeof self !== "undefined" ? self : globalThis);
